# Generated by noon shell init. Source manually; no startup files are modified.
_noon_saved_status=$?
_noon_install() {
    local saved=$1
    autoload -Uz compinit add-zsh-hook
    (( $+functions[compdef] )) || compinit -i -D
    _noon_complete() {
        local -a candidates
        candidates=("${(@f)$(command noon "${(@Q)words[@]:1:$((CURRENT-1))}" --generate-shell-completion 2>/dev/null)}")
        (( ${#candidates} )) && compadd -- "${candidates[@]}"
        return 0
    }
    compdef _noon_complete noon
    add-zsh-hook -d chpwd _noon_chpwd
    _noon_job='@JOB@'
    if [[ -n $_noon_job ]]; then
        _noon_directory=$PWD
        _noon_project=$(command noon shell entry --record -- zsh "$_noon_job" '' "$PWD" "$PWD")
        _noon_chpwd() {
            local saved=$?
            _noon_project=$(command noon shell entry -- zsh "$_noon_job" "$_noon_project" "$_noon_directory" "$PWD")
            _noon_directory=$PWD
            return "$saved"
        }
        add-zsh-hook chpwd _noon_chpwd
    fi
    return "$saved"
}
_noon_install "$_noon_saved_status"
